/* ===================== API HELPER ===================== */
async function apiFetch_(url, opts){
  const controller = new AbortController();
  const timeout = setTimeout(()=>controller.abort(), 15000);
  try{
    const res = await fetch(url, Object.assign({signal: controller.signal}, opts||{}));
    clearTimeout(timeout);
    if(!res.ok){
      return {ok:false, error: 'Server returned HTTP '+res.status+'. Check the deployment is set to "Anyone" access and you copied the /exec URL.'};
    }
    const text = await res.text();
    try{
      return JSON.parse(text);
    }catch(parseErr){
      return {ok:false, error: 'The backend didn\'t return JSON (got a login or error page instead). In Apps Script: Deploy → Manage deployments → check "Who has access" is set to "Anyone", and that you\'re using the …/exec URL, not …/dev.'};
    }
  }catch(err){
    clearTimeout(timeout);
    if(err.name === 'AbortError'){
      return {ok:false, error: 'Request timed out after 15s. The API_URL may be wrong, or the deployment isn\'t reachable.'};
    }
    return {ok:false, error: 'Network/CORS error reaching the backend (' + err.message + '). Double-check API_URL is the exact …/exec URL from Deploy → Manage deployments.'};
  }
}
async function apiGet(action, params){
  const qs = new URLSearchParams(Object.assign({action}, params||{})).toString();
  return apiFetch_(API_URL + '?' + qs, {method:'GET', cache:'no-store'});
}
async function apiPost(body){
  return apiFetch_(API_URL, {method:'POST', body: JSON.stringify(body)});
}

/* ===================== HELPERS ===================== */
function costForItem(item){ return item.baseCost + (eventDay - 1) * 100; }
function fmt(n){ return (n<0?'-':'') + Math.abs(Math.round(n)).toLocaleString(); }
function itemById(id){ return SHOP_ITEMS.find(i=>i.id===id); }
function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function notifIcon(type){
  return {approved:'✅', rejected:'❌', points:'🏆', event:'🎉', admin:'🛡️'}[type] || '🔔';
}

function togglePassword(id, btn){
  const input = document.getElementById(id);
  if(!input) return;
  input.type = input.type === 'password' ? 'text' : 'password';
  if(btn) btn.innerText = input.type === 'password' ? 'SHOW' : 'HIDE';
}

function toast(msg, type){
  const wrap = document.getElementById('toastWrap');
  const el = document.createElement('div');
  el.className = 'toast ' + (type==='bad' ? 'bad' : type==='fun' ? 'fun' : 'ok');
  el.textContent = msg;
  wrap.appendChild(el);
  setTimeout(()=>{ el.style.opacity='0'; el.style.transition='.25s'; setTimeout(()=>el.remove(),260); }, 3800);
}

function checkApiConfigured(){
  if(!API_URL || API_URL.indexOf('PASTE_YOUR') === 0){
    toast('API_URL is not set yet — deploy Code.gs and paste the Web App URL into this file.', 'bad');
    return false;
  }
  return true;
}

/* ===================== TABS ===================== */
function showTab(tab){
  document.querySelectorAll('.tab-btn').forEach(b=>b.classList.toggle('active', b.dataset.tab===tab));
  document.querySelectorAll('.panel').forEach(p=>p.classList.remove('active'));
  document.getElementById('panel-'+tab).classList.add('active');
  if(tab==='dash') renderDash();
  if(tab==='board'){ renderBoard(); }
  if(tab==='notif') renderNotifications();
  if(tab==='admin' && isAdmin) renderAdminNotifications();
}

/* ===================== SHOP HOURS ===================== */
let shopOpen = false;
async function refreshState(){
  if(!checkApiConfigured()) return;
  const r = await apiGet('state');
  if(!r.ok){
    const banner = document.getElementById('hoursBanner');
    const text = document.getElementById('hoursText');
    banner.className = 'hours-banner pxframe closed';
    text.innerText = 'Backend unreachable: ' + r.error;
    return;
  }
  eventDay = r.eventDay;
  shopOpen = r.shopOpen;
  document.getElementById('dayDisplay').innerText = eventDay;
  const banner = document.getElementById('hoursBanner');
  const text = document.getElementById('hoursText');
  banner.className = 'hours-banner pxframe ' + (shopOpen ? 'open' : 'closed');
  if(!r.marketOpen){
    text.innerText = 'The market has been closed by an executive admin — check back soon.';
  } else {
    text.innerText = shopOpen
      ? 'Shop is open — buy your perks now (closes at ' + r.shopCloseHour + ':00).'
      : 'Shop is closed — opens daily at ' + r.shopOpenHour + ':00, closes ' + r.shopCloseHour + ':00.';
  }
  const marketPill = document.getElementById('marketStatusPill');
  if(marketPill) marketPill.innerText = r.marketOpen ? '🟢 MARKET OPEN' : '🔴 MARKET CLOSED';
  renderShop();
  renderAnnouncements();
}

/* ===================== ANNOUNCEMENTS ===================== */
async function renderAnnouncements(){
  const el = document.getElementById('announcementsList');
  if(!el) return;
  const r = await apiGet('announcements', {});
  if(!r.ok || !r.announcements.length){ el.innerHTML = ''; el.style.display='none'; return; }
  el.style.display = '';
  el.innerHTML = r.announcements.map(a=>`
    <div class="notif-item">
      <span class="notif-icon">📣</span>
      <div class="notif-main">
        <div class="notif-msg">${esc(a.message)}</div>
        <div class="notif-time" title="${new Date(a.createdAt).toLocaleString()}">${timeAgo(a.createdAt)}</div>
      </div>
    </div>`).join('');
}

async function createAnnouncement(){
  const input = document.getElementById('annMessage');
  const statusEl = document.getElementById('annStatus');
  const message = input.value.trim();
  if(!message){ statusEl.innerHTML = '<div class="status-msg status-bad">Enter a message first.</div>'; return; }
  const r = await apiPost({action:'createAnnouncement', ...adminAuthParams(), message});
  if(!r.ok){ statusEl.innerHTML = '<div class="status-msg status-bad">'+r.error+'</div>'; return; }
  statusEl.innerHTML = '<div class="status-msg status-ok">Posted.</div>';
  input.value = '';
}

async function setMarket(mode){
  const statusEl = document.getElementById('marketStatus');
  const r = await apiPost({action:'setMarket', ...adminAuthParams(), mode});
  if(!r.ok){ statusEl.innerHTML = '<div class="status-msg status-bad">'+r.error+'</div>'; return; }
  const label = mode === 'auto' ? 'set to AUTO (following the schedule)' : (r.shopOpen ? 'now OPEN' : 'now CLOSED');
  statusEl.innerHTML = '<div class="status-msg status-ok">Market is ' + label + '.</div>';
  refreshState();
}

/* ===================== PERK TICKETS ===================== */
async function downloadTicket(it){
  const def = itemById(it.itemId);
  const artSrc = (def && (def.ticketImg || def.img));
  if(!artSrc){ toast('Ticket art missing for this perk.', 'err'); return; }
  const img = new Image();
  img.crossOrigin = 'anonymous';
  await new Promise((res, rej)=>{ img.onload = res; img.onerror = rej; img.src = artSrc; });

  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth; canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);

  // Overlay a translucent panel + ticket details in the blank space
  // beneath the perk description (matches the reference ticket layout).
  const W = canvas.width, H = canvas.height;
  const panelY = H * 0.775, panelH = H * 0.145;
  ctx.fillStyle = 'rgba(2,14,9,0.55)';
  ctx.fillRect(W*0.04, panelY, W*0.92, panelH);
  ctx.strokeStyle = 'rgba(180,255,220,.35)';
  ctx.lineWidth = 2;
  ctx.strokeRect(W*0.04, panelY, W*0.92, panelH);

  const module = (typeof MODULES !== 'undefined' && MODULES.find) ? MODULES.find(m=>m.moduleId===it.moduleId) : null;
  const lines = [
    `TEAM: ${currentTeam || ''}`,
    `DELEGATION ID: ${(teamData && teamData.delegationId) || '—'}`,
    `MODULE: ${(module && module.name) || it.moduleId || 'General'}`,
    `TICKET CODE: ${it.token || '—'}`
  ];
  ctx.fillStyle = '#eafff4';
  ctx.font = `bold ${Math.round(W*0.032)}px 'Baloo 2', system-ui, sans-serif`;
  ctx.textBaseline = 'top';
  lines.forEach((line, i)=>{
    ctx.fillText(line, W*0.07, panelY + W*0.02 + i*(W*0.037));
  });

  ctx.fillStyle = '#8ff7d0';
  ctx.font = `bold ${Math.round(W*0.028)}px 'Baloo 2', system-ui, sans-serif`;
  ctx.fillText('✔ APPROVED', W*0.07, panelY + panelH - W*0.05);

  const url = canvas.toDataURL('image/png');
  const a = document.createElement('a');
  a.href = url;
  a.download = `BNA27-Ticket-${def.name.replace(/\s+/g,'')}-${it.token||'x'}.png`;
  document.body.appendChild(a); a.click(); a.remove();
  toast('Ticket downloaded! 🎟', 'ok');
}

/* ===================== LOGIN ===================== */
// "Remember me" persists Team ID + password (and email) in this browser's localStorage,
// so returning teams don't have to retype their password every time. The saved password
// is only ever overwritten by a fresh successful login — it's never silently changed.
const REMEMBER_KEY = 'bna27_remember_v1';
function saveRememberedLogin(teamId, password, email){
  try{
    localStorage.setItem(REMEMBER_KEY, JSON.stringify({teamId, password, email}));
  }catch(e){ /* localStorage unavailable (private mode etc.) — fail silently */ }
}
function loadRememberedLogin(){
  try{
    const raw = localStorage.getItem(REMEMBER_KEY);
    return raw ? JSON.parse(raw) : null;
  }catch(e){ return null; }
}
function clearRememberedLogin(){
  try{ localStorage.removeItem(REMEMBER_KEY); }catch(e){}
}

/* Shared "land in the app" step used by password login, Google login, and the
   sign-up-with-an-already-registered-email path — so all three behave identically. */
async function enterMainApp(teamId, team, opts){
  opts = opts || {};
  currentTeam = teamId;
  teamData = team;
  if(opts.remember && opts.password){ saveRememberedLogin(teamId, opts.password, opts.email||''); }
  else if(opts.remember === false){ clearRememberedLogin(); }
  document.getElementById('loginWrap').style.display='none';
  document.getElementById('mainWrap').style.display='block';
  document.getElementById('teamLabel').innerText = 'TEAM: ' + teamId;
  await refreshState();
  renderAll();
  if(opts.welcome) toast(opts.welcome, 'ok');
}

async function login(){
  if(!checkApiConfigured()) return;
  const teamId = document.getElementById('teamIdInput').value.trim().toUpperCase();
  const password = document.getElementById('teamPassInput').value;
  const email = document.getElementById('teamEmailInput').value.trim();
  const statusEl = document.getElementById('loginStatus');
  if(!teamId || !password){ statusEl.innerText = 'Enter a Team ID and password.'; return; }
  statusEl.innerText = 'Signing in…';
  const r = await apiPost({action:'login', teamId, password, email});
  if(!r.ok){ statusEl.innerText = r.error; return; }
  if(r.found === false){
    statusEl.innerText = '';
    document.getElementById('signupTeamId').value = teamId;
    document.getElementById('signupPassInput').value = password;
    document.getElementById('signupEmailInput').value = email;
    showSignup('No account found for that Team ID — create one below.');
    return;
  }
  const remember = document.getElementById('rememberMeCheck');
  await enterMainApp(teamId, r.team, {remember: !!(remember && remember.checked), password, email, welcome: r.created ? ('New team created — welcome aboard, ' + teamId + '! 🚀') : null});
}

/* ===================== SIGN IN WITH GOOGLE ===================== */
function initGoogleSignIn(){
  if(!GOOGLE_CLIENT_ID || typeof google === 'undefined' || !google.accounts) return;
  google.accounts.id.initialize({ client_id: GOOGLE_CLIENT_ID, callback: handleGoogleCredential });
  const loginSlot = document.getElementById('googleBtnLogin');
  const signupSlot = document.getElementById('googleBtnSignup');
  if(loginSlot) google.accounts.id.renderButton(loginSlot, { theme:'filled_black', size:'large', text:'signin_with', shape:'pill' });
  if(signupSlot) google.accounts.id.renderButton(signupSlot, { theme:'filled_black', size:'large', text:'signup_with', shape:'pill' });
}

async function handleGoogleCredential(response){
  const statusEl = document.getElementById('loginStatus');
  if(statusEl) statusEl.innerText = 'Verifying with Google…';
  const r = await apiPost({action:'googleLogin', credential: response.credential});
  if(!r.ok){ if(statusEl) statusEl.innerText = r.error; return; }
  if(r.needsSignup){
    document.getElementById('signupEmailInput').value = r.email;
    document.getElementById('signupEmailInput').readOnly = true;
    showSignup('No BNA\'27 account found for ' + r.email + ' yet — finish creating your team below.');
    return;
  }
  await enterMainApp(r.team.teamId, r.team, {remember:false, welcome:'Signed in with Google — welcome back!'});
}
function logout(){
  currentTeam = null; teamData = null;
  isAdmin = false; adminIdCache = ''; adminPasswordCache = ''; adminRole = ''; adminModuleId = '';
  clearRememberedLogin();
  document.getElementById('mainWrap').style.display='none';
  document.getElementById('loginWrap').style.display='block';
  document.getElementById('teamPassInput').value='';
  document.getElementById('adminPasswordInput').value='';
  document.querySelector('.tabs').style.display='';
  document.getElementById('hoursBanner').style.display='';
  document.querySelectorAll('.teaminfo .pill.day, .teaminfo .pill.points, .teaminfo .pill.balance').forEach(el=>el.style.display='');
  document.getElementById('adminPanel').style.display='none';
  setLoginMode('team');
}

/* Auto sign-in on page load if this device has a remembered login. */
async function tryAutoLogin(){
  const saved = loadRememberedLogin();
  if(!saved || !saved.teamId || !saved.password) return;
  document.getElementById('teamIdInput').value = saved.teamId;
  document.getElementById('teamPassInput').value = saved.password;
  document.getElementById('teamEmailInput').value = saved.email || '';
  const statusEl = document.getElementById('loginStatus');
  if(statusEl) statusEl.innerText = 'Signing you back in…';
  await login();
}

/* ===================== LOGIN MODE (Team / Signup / Admin) ===================== */
function setLoginMode(mode){
  if(mode !== 'signup'){ const se = document.getElementById('signupEmailInput'); if(se) se.readOnly = false; }
  document.getElementById('loginCardInner').style.display = mode==='team' ? 'block' : 'none';
  document.getElementById('signupCard').style.display = mode==='signup' ? 'block' : 'none';
  document.getElementById('adminLoginCard').style.display = mode==='admin' ? 'block' : 'none';
  document.getElementById('modeTabTeam').classList.toggle('active', mode==='team');
  document.getElementById('modeTabSignup').classList.toggle('active', mode==='signup');
  document.getElementById('modeTabAdmin').classList.toggle('active', mode==='admin');
  const footer = document.getElementById('loginModeFooter');
  footer.style.display = mode==='admin' ? 'none' : 'block';
  document.getElementById('loginStatus').innerText = '';
  document.getElementById('signupStatus').innerText = '';
  document.getElementById('adminLoginStatus').innerText = '';
}
// Kept as aliases since other code/links may still reference the old names.
function showSignup(msg){ setLoginMode('signup'); if(msg) document.getElementById('signupStatus').innerText = msg; }
function showLogin(){ setLoginMode('team'); }

/* ===================== SIGNUP ===================== */
async function signup(){
  if(!checkApiConfigured()) return;
  const teamId = document.getElementById('signupTeamId').value.trim().toUpperCase();
  const email = document.getElementById('signupEmailInput').value.trim();
  const password = document.getElementById('signupPassInput').value;
  const statusEl = document.getElementById('signupStatus');
  const orionModule = document.getElementById('signupOrion') ? document.getElementById('signupOrion').value : '';
  const siriusModule = document.getElementById('signupSirius') ? document.getElementById('signupSirius').value : '';
  const polarisModule = document.getElementById('signupPolaris') ? document.getElementById('signupPolaris').value : '';
  const vegaModule = document.getElementById('signupVega') ? document.getElementById('signupVega').value : '';
  if(!/^\d{3}$/.test(teamId)){ statusEl.innerText = 'Team number must be exactly 3 digits. Team names are not allowed. Please sign up again using a 3-digit number.'; return; }
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)){ statusEl.innerText = 'That email address looks invalid. Sign up again with a valid email address.'; return; }
  if(!password || password.length < 4){ statusEl.innerText = 'Password must be at least 4 characters. Sign up again with a stronger password.'; return; }
  const groupsChosen = [orionModule, siriusModule, polarisModule, vegaModule].filter(Boolean).length;
  if(teamId && groupsChosen !== REQUIRED_GROUP_COUNT){
    statusEl.innerText = `Pick exactly one module from ${REQUIRED_GROUP_COUNT} of the 4 groups (Orion/Sirius/Polaris/Vega) — you've picked ${groupsChosen}.`;
    return;
  }
  // Team ID and modules are only required for a brand-new account — if this email is
  // already registered, the backend logs you into that existing account instead, so we
  // don't block that path on fields an existing team doesn't need to re-enter.
  statusEl.innerText = 'Checking…';
  const r = await apiPost({action:'signup', teamId, email, password, orionModule, siriusModule, polarisModule, vegaModule});
  if(!r.ok){ statusEl.innerText = r.error; return; }
  if(r.emailWarning) toast(r.emailWarning, 'bad');

  if(r.existingAccount){
    // This email was already registered — same Team ID and Delegation ID as before, just
    // your new password now works. Log straight in, no separate "account created" message.
    const remember = document.getElementById('rememberMeCheck');
    await enterMainApp(r.team.teamId, r.team, {remember: !!(remember && remember.checked), password, email, welcome: 'Welcome back, ' + r.team.teamId + '! Your password has been updated.'});
    return;
  }

  toast('Account created! Delegation ID: ' + (r.team && r.team.delegationId), 'ok');
  showLogin();
  document.getElementById('teamIdInput').value = teamId;
  document.getElementById('teamPassInput').value = password;
  document.getElementById('teamEmailInput').value = email;
  await login();
}

/* ===================== SHOP RENDER ===================== */
function purchaseCountFor(itemId, moduleId){
  if(!teamData || !teamData.purchaseCounts || !moduleId) return 0;
  return teamData.purchaseCounts[itemId+'__'+moduleId] || 0;
}

/* Plain-language version of the shared per-module purchase limit, e.g.
   "This perk can be bought by 3 teams only, first come first serve basis — once
   it's been bought 3 times, it runs out." Singular-safe for 1-of-a-kind perks. */
function stockLimitText(item){
  const n = item.maxPerModule;
  const teamsWord = n === 1 ? 'team' : 'teams';
  const timesPhrase = n === 1 ? 'once' : n + ' times';
  return `This perk can be bought by ${n} ${teamsWord} only per module — first come, first served. Once it's been bought ${timesPhrase}, it runs out.`;
}

function renderShop(){
  const grid = document.getElementById('shopGrid');
  if(!grid) return;
  const moduleSel = document.getElementById('shopModuleSelect');
  const moduleId = moduleSel ? moduleSel.value : '';
  grid.innerHTML = SHOP_ITEMS.map(item=>{
    const cost = costForItem(item);
    const affordable = teamData ? teamData.balance >= cost : true;
    const bought = purchaseCountFor(item.id, moduleId);
    const capped = !!moduleId && bought >= item.maxPerModule;
    const canBuy = affordable && shopOpen && !!moduleId && !capped;
    const extra = item.isTarget
      ? `<div class="heist-target">
           <select id="target-${item.id}" aria-label="Choose opponent team">
             <option value="">Choose opponent team…</option>
           </select>
           <p class="target-loading" id="target-loading-${item.id}">Loading eligible opponent teams…</p>
           <p class="heist-note">Choose a team registered in the selected module. Requires admin approval.</p>
         </div>`
      : '';
    let label = 'BUY';
    if(!shopOpen) label = 'CLOSED';
    else if(!moduleId) label = 'PICK MODULE';
    else if(capped) label = 'LIMIT REACHED';
    else if(!affordable) label = 'INSUFFICIENT CREDITS';
    const stockBadge = moduleId
      ? (capped ? '<span class="stock-badge out">OUT OF STOCK</span>' : '<span class="stock-badge in">IN STOCK</span>')
      : '';
    return `
    <div class="card pxframe rarity-${item.rarity}">
      <div class="card-head"><span>${item.name}</span><div style="display:flex;gap:6px;align-items:center">${stockBadge}<span class="rarity-tag">${TIER_LABELS[item.rarity]||item.rarity}</span></div></div>
      <div class="card-art"><img src="${item.img}" alt="${item.name}"></div>
      <div class="card-body">
        <p>${item.desc}</p>
        <p class="heist-note" style="color:var(--muted)">${stockLimitText(item)}${moduleId?` (${bought}/${item.maxPerModule} bought for this module so far)`:''}</p>
        ${extra}
        <div class="cost-row">
          <span class="cost"><img class="coinicon" src="${COIN_DATA_URI}">${fmt(cost)}</span>
          <button class="buy-btn" ${canBuy?'':'disabled'} onclick="buyItem('${item.id}')">${label}</button>
        </div>
      </div>
    </div>`;
  }).join('');
  attachCardTilt(grid);
  populateHeistTargetDropdowns_(moduleId);
}

async function populateHeistTargetDropdowns_(moduleId){
  const targetItems = SHOP_ITEMS.filter(item=>item.isTarget);
  if(!targetItems.length) return;
  for(const item of targetItems){
    const select = document.getElementById('target-'+item.id);
    const note = document.getElementById('target-loading-'+item.id);
    if(!select) continue;
    if(!moduleId){
      select.innerHTML = '<option value="">Choose a module first</option>';
      select.disabled = true;
      if(note) note.textContent = 'Select a module above to see eligible opponent teams.';
      continue;
    }
    select.disabled = true;
    if(note) note.textContent = 'Loading eligible opponent teams…';
    try{
      const r = await apiGet('eligibleTargets',{moduleId,teamId:currentTeam,_ts:Date.now()});
      if(!r.ok) throw new Error(r.error || 'Could not load teams');
      const teams = (r.teams||[]).filter(t =>
        String(t.teamId).toUpperCase() !== String(currentTeam||'').toUpperCase()
      );
      if(!teams.length){
        select.innerHTML = '<option value="">No other eligible teams</option>';
        if(note) note.textContent = 'No other eligible team is registered in this module yet.';
      }else{
        select.innerHTML = '<option value="">Choose opponent team…</option>' +
          teams.map(t=>`<option value="${esc(t.teamId)}">${esc(t.teamId)}</option>`).join('');
        if(note) note.textContent = `${teams.length} eligible opponent team${teams.length===1?'':'s'} available · your team is excluded`;
      }
    }catch(err){
      select.innerHTML = '<option value="">Could not load opponents</option>';
      if(note) note.textContent = 'Could not load eligible teams — refresh and try again.';
    }
    select.disabled = false;
  }
}

async function buyItem(itemId){
  if(!checkApiConfigured()) return;
  if(!currentTeam){ toast('Log in first.', 'bad'); return; }
  const item = itemById(itemId);
  const cost = costForItem(item);
  const moduleSel = document.getElementById('shopModuleSelect');
  const moduleId = moduleSel ? moduleSel.value : '';
  if(!moduleId){ toast('Choose which module you\'re buying this perk for first.', 'bad'); return; }
  if(purchaseCountFor(itemId, moduleId) >= item.maxPerModule){ toast(`This perk is out of stock for that module — it's already been bought by the max of ${item.maxPerModule} team${item.maxPerModule===1?'':'s'}.`, 'bad'); return; }
  if(teamData.balance < cost){ toast('Not enough BOBUX for that yet.', 'bad'); return; }

  let target = null;
  if(item.isTarget){
    target = (document.getElementById('target-'+itemId)?.value || '').trim().toUpperCase();
    if(!target){ toast('Choose an opponent team first.', 'bad'); return; }
    if(target === currentTeam){ toast("You can't target your own team.", 'bad'); return; }
  }

  const r = await apiPost({action:'buy', teamId: currentTeam, itemId: item.id, itemName: item.name, cost, rarity: item.rarity, target, moduleId, maxPerModule: item.maxPerModule});
  if(!r.ok){ toast(r.error, 'bad'); return; }
  toast('Request sent — waiting on a admin to approve "'+item.name+'".', 'ok');
  if(item.isTarget){ const targetSelect=document.getElementById('target-'+itemId); if(targetSelect) targetSelect.value=''; }
  if(r.purchaseCounts) teamData.purchaseCounts = r.purchaseCounts;
  renderShop();
  renderMyRequests();
  updatePendingBadge();
}

/* ===================== MY REQUESTS / DASHBOARD ===================== */
async function renderMyRequests(){
  const el = document.getElementById('myRequests');
  if(!el || !currentTeam) return;
  el.innerHTML = '<p class="empty">Loading…</p>';
  const r = await apiGet('requests', {teamId: currentTeam});
  if(!r.ok){ el.innerHTML = '<p class="empty">Could not load requests.</p>'; return; }
  const mine = r.requests;
  document.getElementById('statPending').innerText = mine.filter(x=>x.status==='pending').length;
  if(!mine.length){ el.innerHTML = '<p class="empty">No requests yet — buy something in the SHOP.</p>'; return; }
  el.innerHTML = mine.map(req=>{
    const it = itemById(req.itemId);
    return `
    <div class="req-item">
      <img src="${it?it.img:''}" alt="">
      <div class="req-main">
        <div class="req-name">${esc(req.itemName)}${req.target?' → '+esc(req.target):''}</div>
        <div class="req-meta">${fmt(req.cost)} BOBUX${req.moduleId?' · '+esc((MODULES.find(m=>m.moduleId===req.moduleId)||{}).name||req.moduleId):''} · ${new Date(req.timestamp).toLocaleString()}${req.status==='approved' && req.token ? ' · token '+esc(req.token) : ''}${req.note?' · '+esc(req.note):''}</div>
      </div>
      <span class="status-pill status-${req.status}">${req.status}</span>
    </div>`;
  }).join('');
}

async function renderDash(){
  if(!currentTeam) return;
  const r = await apiGet('team', {teamId: currentTeam, password: document.getElementById('teamPassInput').value || ''});
  if(r.ok) teamData = r.team;
  countUpTo(document.getElementById('statBalance'), teamData.balance);
  countUpTo(document.getElementById('statPoints'), teamData.points||0);
  countUpTo(document.getElementById('pointsDisplay'), teamData.points||0);
  updateNotifBadge();

  const inv = document.getElementById('invGrid');
  if(!teamData.inventory || !teamData.inventory.length){
    inv.innerHTML = '<div class="inv-empty">Your inventory is empty. Approved purchases show up here.</div>';
  } else {
    inv.innerHTML = teamData.inventory.map(it=>{
      const def = itemById(it.itemId);
      return `
      <div class="inv-slot rarity-${it.rarity}" title="${esc(it.name)} x${it.qty||1}">
        <div class="inv-slot-inner">
          <img src="${def?def.img:''}" alt="">
          <div class="inv-name">${esc(it.name)}</div>
        </div>
        ${(it.qty||1)>1?`<span class="inv-qty">x${it.qty}</span>`:''}
        ${it.token?`<button class="ticket-btn" onclick='downloadTicket(${JSON.stringify(it).replace(/'/g,"&#39;")})'>🎟 Ticket</button>`:''}
      </div>`;
    }).join('');
  }

  const hist = document.getElementById('myHistory');
  if(!teamData.history || !teamData.history.length){
    hist.innerHTML = '<p class="empty">No transactions yet.</p>';
  } else {
    hist.innerHTML = teamData.history.slice(0,25).map(h=>`
      <div class="hist-item">
        <span>${esc(h.reason)}<br><span style="opacity:.6;font-size:11.5px">${new Date(h.ts).toLocaleString()}</span></span>
        <span class="${h.delta>=0?'pos':'neg'}">${h.delta>=0?'+':''}${fmt(h.delta)}</span>
      </div>`).join('');
  }
  renderMyRequests();
  countUpTo(document.getElementById('balanceDisplay'), teamData.balance);
}

function renderAll(){
  countUpTo(document.getElementById('balanceDisplay'), teamData.balance);
  countUpTo(document.getElementById('pointsDisplay'), teamData.points||0);
  renderShop();
  renderDash();
  updatePendingBadge();
  updateNotifBadge();
}

async function updatePendingBadge(){
  if(!isAdmin) return;
  const r = await apiGet('pending', {...adminAuthParams()});
  const badge = document.getElementById('adminBadge');
  if(r.ok && r.pending.length){ badge.style.display='inline-block'; badge.innerText = r.pending.length; }
  else { badge.style.display='none'; }
}

/* ===================== NOTIFICATIONS (team) ===================== */
// Short relative-time label ("2m ago", "Just now") with a full timestamp on hover.
function timeAgo(dateStr){
  const d = new Date(dateStr);
  const diffSec = Math.max(0, Math.floor((Date.now() - d.getTime())/1000));
  if(diffSec < 30) return 'Just now';
  if(diffSec < 60) return diffSec + 's ago';
  const diffMin = Math.floor(diffSec/60);
  if(diffMin < 60) return diffMin + 'm ago';
  const diffHr = Math.floor(diffMin/60);
  if(diffHr < 24) return diffHr + 'h ago';
  const diffDay = Math.floor(diffHr/24);
  if(diffDay < 7) return diffDay + 'd ago';
  return d.toLocaleDateString();
}

async function renderNotifications(){
  const el = document.getElementById('notifList');
  if(!el || !currentTeam) return;
  el.innerHTML = '<p class="empty">Loading…</p>';
  const r = await apiGet('notifications', {teamId: currentTeam});
  if(!r.ok){ el.innerHTML = '<p class="empty">Couldn\'t load notifications — ' + esc(r.error) + ' <a href="#" onclick="renderNotifications();return false;" style="color:var(--mint2);text-decoration:underline">Retry</a></p>'; return; }
  const notifs = (r.notifications || []).slice().sort((a,b)=> new Date(b.createdAt) - new Date(a.createdAt));
  if(!notifs.length){ el.innerHTML = '<p class="empty">No notifications yet — approvals, points and event bonuses will show up here.</p>'; }
  else {
    el.innerHTML = notifs.map(n=>`
      <div class="notif-item ${!n.read?'unread':''}">
        <span class="notif-icon type-${esc(n.type||'points')}">${notifIcon(n.type)}</span>
        <div class="notif-main">
          <div class="notif-msg">${esc(n.message)}</div>
          <div class="notif-time" title="${new Date(n.createdAt).toLocaleString()}">${timeAgo(n.createdAt)}</div>
        </div>
        ${!n.read?'<span class="pill" style="background:var(--coral)">NEW</span>':''}
      </div>`).join('');
  }
  if(r.unread){
    await apiPost({action:'markNotificationsRead', teamId: currentTeam});
    const tabBadge = document.getElementById('notifBadge');
    const statEl = document.getElementById('statNotif');
    if(tabBadge) tabBadge.style.display='none';
    if(statEl) statEl.innerText = 0;
  }
}

// Lightweight poll (no mark-as-read) just to keep tab/dashboard badges live.
async function updateNotifBadge(){
  if(!currentTeam) return;
  const r = await apiGet('notifications', {teamId: currentTeam});
  if(!r.ok) return;
  const tabBadge = document.getElementById('notifBadge');
  const statEl = document.getElementById('statNotif');
  if(tabBadge){ if(r.unread){ tabBadge.style.display='inline-block'; tabBadge.innerText = r.unread; } else { tabBadge.style.display='none'; } }
  if(statEl) statEl.innerText = r.unread || 0;
  // If the notifications tab is currently open, keep the visible list live too.
  const panel = document.getElementById('panel-notif');
  if(panel && panel.classList.contains('active')) renderNotifications();
}

/* ===================== LEADERBOARD ===================== */
function setBoardMetric(metric){
  const p=document.getElementById('boardMetricPoints'), b=document.getElementById('boardMetricBobux');
  if(p) p.classList.toggle('active',metric==='points');
  if(b) b.classList.toggle('active',metric==='bobux');
  const sel=document.getElementById('boardMetricSelect'); if(sel) sel.value=metric;
  renderBoard();
}
function populateBoardModuleFilter(){
  const sel=document.getElementById('boardModuleSelect'); if(!sel || sel.dataset.ready==='1') return;
  const groups={};
  MODULES.forEach(m=>{ if(!groups[m.group]) groups[m.group]=[]; groups[m.group].push(m); });
  Object.keys(groups).forEach(group=>{
    const og=document.createElement('optgroup'); og.label=group;
    groups[group].forEach(m=>{ const o=document.createElement('option'); o.value=m.moduleId; o.textContent=m.name; og.appendChild(o); });
    sel.appendChild(og);
  });
  const trib=document.createElement('optgroup'); trib.label='TRIBULATIONS';
  [{moduleId:'bsx',name:'BSX (Secrets of Vault 27)'},{moduleId:'blueprint_time',name:'Blueprint of Time'}].forEach(m=>{const o=document.createElement('option');o.value=m.moduleId;o.textContent=m.name;trib.appendChild(o);});
  sel.appendChild(trib); sel.dataset.ready='1';
}
function boardValue(row,metric){return metric==='bobux' ? Number(row.balance)||0 : Number(row.points)||0;}
function boardLabel(metric){return metric==='bobux' ? 'BOBUX' : 'POINTS';}
let boardRenderSeq=0;
let previousBoardRanks={};
async function renderBoard(){
  const seq=++boardRenderSeq;
  const podium=document.getElementById('boardPodium'), body=document.getElementById('boardBody'), ctx=document.getElementById('boardContext');
  if(!body) return;
  const metric=(document.getElementById('boardMetricSelect')?.value) || (document.getElementById('boardMetricBobux')?.classList.contains('active')?'bobux':'points');
  const moduleId=''; // Team-facing leaderboard is always overall event
  const label=boardLabel(metric);
  const stats={teams:document.getElementById('boardTeamCount'),top:document.getElementById('boardTopScore'),rank:document.getElementById('boardYourRank'),metric:document.getElementById('boardMetricLabel')};
  if(stats.metric) stats.metric.innerText=label;
  if(stats.rank) stats.rank.innerText=currentTeam ? '…' : 'Sign in';
  if(body) body.innerHTML='<div class="board-row board-loading-row" style="justify-content:center;color:var(--muted)"><span class="live-dot"></span>&nbsp; Loading live standings…</div>';
  if(podium) podium.innerHTML='';
  if(ctx) ctx.innerHTML='';

  let r;
  try{
    for(let attempt=1; attempt<=3; attempt++){
      r=await apiGet('board',{metric,moduleId,_ts:Date.now()});
      if(r && r.ok) break;
      if(attempt<3) await new Promise(resolve=>setTimeout(resolve,600*attempt));
    }
  }
  catch(err){
    if(seq!==boardRenderSeq) return;
    body.innerHTML='<div class="board-row" style="flex-direction:column;gap:8px;justify-content:center;color:var(--coral);text-align:center"><span>Could not load standings. Check the connection and try again.</span><button class="action ghost" style="margin:0;padding:8px 16px;font-size:11.5px" onclick="renderBoard()">↻ RETRY</button></div>';
    if(stats.rank) stats.rank.innerText=currentTeam ? 'Unavailable' : 'Sign in';
    return;
  }
  if(seq!==boardRenderSeq) return;
  if(!r || !r.ok){
    body.innerHTML='<div class="board-row" style="flex-direction:column;gap:8px;justify-content:center;color:var(--coral);text-align:center"><span>'+esc((r&&r.error)||'Could not load standings.')+'</span><button class="action ghost" style="margin:0;padding:8px 16px;font-size:11.5px" onclick="renderBoard()">↻ RETRY</button></div>';
    if(stats.rank) stats.rank.innerText=currentTeam ? 'Unavailable' : 'Sign in';
    return;
  }

  const board=r.board||[];
  const nowRanks={};
  board.forEach((row,i)=>nowRanks[row.teamId]=i+1);
  if(stats.teams) stats.teams.innerText=fmt(board.length);
  if(stats.top) stats.top.innerText=board.length?fmt(boardValue(board[0],metric)):'—';
  if(!board.length){
    body.innerHTML='<div class="board-row" style="justify-content:center;color:var(--muted)">No teams in this view yet.</div>';
    if(stats.rank) stats.rank.innerText='—';
    previousBoardRanks=nowRanks;
    return;
  }

  const myIndex=currentTeam ? board.findIndex(x=>String(x.teamId).toUpperCase()===String(currentTeam).toUpperCase()) : -1;
  if(stats.rank) stats.rank.innerText=myIndex>=0 ? '#'+(myIndex+1) : (currentTeam ? 'Not ranked' : 'Sign in');
  const selectedName=moduleId ? ((MODULES.find(m=>m.moduleId===moduleId)||{}).name || (moduleId==='bsx'?'BSX (Secrets of Vault 27)':moduleId==='blueprint_time'?'Blueprint of Time':moduleId)) : 'Overall event';
  const myRow=myIndex>=0?board[myIndex]:null;
  const above=myIndex>0?board[myIndex-1]:null;
  const gap=above && myRow ? Math.max(0,boardValue(above,metric)-boardValue(myRow,metric)) : 0;
  const ticker=document.getElementById('boardTicker');
  if(ticker){
    if(myRow && myIndex===0) ticker.innerHTML='Your team is <b>#1</b> — protect the lead.';
    else if(myRow && myIndex>0) ticker.innerHTML='Your team is <b>#'+(myIndex+1)+'</b> — <b>'+fmt(gap)+'</b> '+label.toLowerCase()+' to climb.';
    else ticker.textContent='Live standings · '+fmt(board.length)+' teams ranked';
  }

  if(ctx){
    ctx.innerHTML=`
      <div class="board-context-card"><span class="label">Viewing</span><b>${esc(selectedName)}</b></div>
      <div class="board-context-card"><span class="label">Metric</span><b>${label}</b></div>
      <div class="board-context-card highlight"><span class="label">Your position</span><b>${myIndex>=0?'#'+(myIndex+1):(currentTeam?'Not ranked':'Sign in')}</b></div>
      <div class="board-context-card"><span class="label">Gap to next rank</span><b>${myIndex>0?fmt(gap)+' '+label.toLowerCase():'—'}</b></div>`;
  }

  const medalClass=['gold','silver','bronze'], medalIcon=['🥇','🥈','🥉'];
  if(podium){
    const top3=board.slice(0,3);
    podium.innerHTML=top3.map((row,i)=>{
      const val=boardValue(row,metric), sub=metric==='bobux'?fmt(row.points)+' pts':fmt(row.balance)+' BOBUX';
      const movement=previousBoardRanks[row.teamId] ? previousBoardRanks[row.teamId]- (i+1) : 0;
      const moveTxt=movement>0?`↑ ${movement}`:movement<0?`↓ ${Math.abs(movement)}`:'LIVE';
      return `<div class="podium-step podium-${medalClass[i]}">
        <div class="podium-medal">${medalIcon[i]}</div>
        <div class="podium-team">${esc(row.teamId)}</div>
        <div class="podium-stats main-score" style="font-size:${i===0?'25px':'19px'};color:var(--ink);font-weight:800">${fmt(val)} ${label}</div>
        <div class="podium-stats">${sub}</div>
        <div style="margin-top:9px;font-size:10px;font-weight:900;color:${movement>0?'var(--mint2)':movement<0?'var(--coral)':'var(--muted)'}">${moveTxt}</div>
      </div>`;
    }).join('');
  }

  body.innerHTML=board.map((row,i)=>{
    const isTop3=i<3,isMe=currentTeam && String(row.teamId).toUpperCase()===String(currentTeam).toUpperCase(),val=boardValue(row,metric);
    const above=i>0?board[i-1]:null;
    const gapRow=above?Math.max(0,boardValue(above,metric)-val):0;
    const previous=previousBoardRanks[row.teamId];
    const delta=previous ? previous-(i+1) : 0;
    const movement=delta>0?`<span style="color:var(--mint2)">↑ ${delta}</span>`:delta<0?`<span style="color:var(--coral)">↓ ${Math.abs(delta)}</span>`:'<span style="color:var(--muted)">•</span>';
    const secondary=metric==='bobux'?`${fmt(row.points)} <span class="board-unit">pts</span>`:`${fmt(row.balance)} <span class="board-unit">BOBUX</span>`;
    const icon=medalIcon[i]||('#'+(i+1));
    return `<div class="board-row ${isTop3?'board-row-top':''} ${isMe?'board-row-me':''}">
      <span class="board-rank">${icon}</span>
      <span class="board-team-wrap"><span class="team-rank-icon">${esc((row.teamId||'?').slice(0,2))}</span><span><span class="board-team">${esc(row.teamId)}${isMe?' <span class="board-you-tag">YOU</span>':''}</span><span class="rank-gap">${i===0?'#1 at the summit':gapRow?fmt(gapRow)+' '+label.toLowerCase()+' behind #'+i:'Tied with #'+i}</span></span></span>
      <span class="${metric==='bobux'?'board-balance':'board-points'}">${metric==='bobux'?`<img class="coinicon" src="${COIN_DATA_URI}" alt="">`:''}${fmt(val)} <span class="board-unit">${label}</span></span>
      <span class="board-${metric==='bobux'?'points':'balance'}">${secondary} · ${movement}</span>
    </div>`;
  }).join('');

  if(myIndex>=0){
    const my=board[myIndex], next=board[myIndex-1];
    const pct=myIndex===0?100:Math.max(0,Math.min(100,next?(boardValue(my,metric)/Math.max(1,boardValue(next,metric)))*100:100));
    body.insertAdjacentHTML('beforeend',`<div class="you-rank-card"><div class="big-rank">#${myIndex+1}</div><div class="you-main"><b>${esc(my.teamId)} · your current live standing</b><span>${myIndex===0?'You are currently leading this view.':fmt(gap)+' '+label.toLowerCase()+' to climb one place'}</span></div><div class="rank-progress"><i style="--p:${pct}%"></i></div><strong style="color:var(--mint2);font-size:12px">${fmt(boardValue(my,metric))} ${label}</strong></div>`);
  } else if(currentTeam){
    body.insertAdjacentHTML('beforeend',`<div class="you-rank-card"><div class="big-rank">—</div><div class="you-main"><b>${esc(currentTeam)} · not ranked yet</b><span>This team is not in the selected leaderboard view.</span></div></div>`);
  }
  previousBoardRanks=nowRanks;
}
/* ===================== ADMIN ===================== */
async function adminLoginSubmit(){
  if(!checkApiConfigured()) return;
  const adminId = document.getElementById('adminIdInput').value.trim().toUpperCase();
  const adminPassword = document.getElementById('adminPasswordInput').value;
  const statusEl = document.getElementById('adminLoginStatus');
  if(!adminId || !adminPassword){ statusEl.innerText = 'Enter your admin ID and password.'; return; }
  statusEl.innerText = 'Checking…';
  const r = await apiPost({action:'adminLogin', adminId, adminPassword});
  if(!r.ok){ statusEl.innerText = r.error; return; }
  adminIdCache = adminId;
  adminPasswordCache = adminPassword;
  isAdmin = true;
  adminRole = r.admin.role;
  adminModuleId = r.admin.moduleId || '';
  statusEl.innerText = '';
  enterAdminMode(r.admin);
}

/* Switches the whole app chrome into "admin mode": team tabs are hidden, only the
   ADMIN tab is shown, and sections inside it are shown/hidden per role. */
function enterAdminMode(admin){
  document.getElementById('loginWrap').style.display = 'none';
  document.getElementById('mainWrap').style.display = 'block';
  document.querySelector('.tabs').style.display = 'none';
  document.getElementById('hoursBanner').style.display = 'none';
  document.getElementById('announcementsList').style.display = 'none';
  document.getElementById('teamLabel').innerText = 'ADMIN: ' + admin.adminId + ' (' + (admin.role==='executive' ? 'EXECUTIVE COUNCIL' : 'MODULE HEAD — ' + (admin.moduleName||admin.moduleId)) + ')';
  document.querySelectorAll('.teaminfo .pill.day, .teaminfo .pill.points, .teaminfo .pill.balance').forEach(el=>el.style.display='none');
  document.getElementById('adminGate').style.display = 'none';
  document.getElementById('adminPanel').style.display = 'block';
  applyAdminRoleVisibility();
  showTab('admin');
  refreshState();
  renderAdminList();
  renderAdminBoard();
  renderItemOwners();
  renderPendingList();
  renderAdminNotifications();
  populateAdminTeamDropdowns();
  populateLockControls();
  const scope=document.getElementById('adminBoardScope');
  if(scope){
    scope.innerHTML = adminRole==='module_head'
      ? '<option value="own">MY MODULE</option><option value="overall">OVERALL EVENT</option>'
      : '<option value="overall">OVERALL EVENT</option>';
  }
  renderAdminBoard();
}

/* Hides sections that are Executive-only when the signed-in admin is a module head,
   and narrows the "award points" module dropdown to just their own module. */
function applyAdminRoleVisibility(){
  const executiveOnlyIds = ['adminDayBox','adminAdjustBox','adminResetPasswordBox','adminAllTeamsBox','adminAnnouncementBox','adminMarketBox','adminPointLocksBox','adminDeleteTeamBox'];
  const isExec = adminRole === 'executive';
  executiveOnlyIds.forEach(id=>{
    const el = document.getElementById(id);
    if(el) el.style.display = isExec ? '' : 'none';
  });

  const myModule = MODULES.find(m=>m.moduleId===adminModuleId);
  const myTribulation = TRIBULATIONS.find(t=>t.moduleId===adminModuleId);

  // AWARD MODULE POINTS box: exec sees the full dropdown; a module head locked to a
  // regular module sees only their module; a tribulation head never sees this box at all.
  const modBox = document.getElementById('adminModulePointsBox');
  const mpSel = document.getElementById('mpModule');
  if(modBox && mpSel){
    if(isExec){
      modBox.style.display = '';
      mpSel.innerHTML = MODULES.map(m=>`<option value="${m.moduleId}">${esc(m.name)}</option>`).join('');
      mpSel.disabled = false;
    } else if(myModule){
      modBox.style.display = '';
      mpSel.innerHTML = `<option value="${myModule.moduleId}">${esc(myModule.name)}</option>`;
      mpSel.disabled = true;
    } else {
      modBox.style.display = 'none';
    }
  }

  // AWARD TRIBULATION POINTS box: exec sees both; a tribulation head sees only theirs
  // locked; a regular module head never sees this box at all.
  const tribBox = document.getElementById('adminTribulationBox');
  const tpSel = document.getElementById('tpTribulation');
  if(tribBox && tpSel){
    if(isExec){
      tribBox.style.display = '';
      tpSel.innerHTML = TRIBULATIONS.map(t=>`<option value="${t.moduleId}">${esc(t.name)}</option>`).join('');
      tpSel.disabled = false;
    } else if(myTribulation){
      tribBox.style.display = '';
      tpSel.innerHTML = `<option value="${myTribulation.moduleId}">${esc(myTribulation.name)}</option>`;
      tpSel.disabled = true;
    } else {
      tribBox.style.display = 'none';
    }
  }
}

async function setEventDayFromInput(){
  const n = parseInt(document.getElementById('setDayInput').value,10);
  const statusEl = document.getElementById('dayStatus');
  if(isNaN(n) || n<1 || n>3){ statusEl.innerHTML = '<div class="status-msg status-bad">Enter a valid day (1–3) — this event only runs 3 days.</div>'; return; }
  const r = await apiPost({action:'setDay', ...adminAuthParams(), day:n});
  if(!r.ok){ statusEl.innerHTML = '<div class="status-msg status-bad">'+r.error+'</div>'; return; }
  eventDay = r.eventDay;
  document.getElementById('dayDisplay').innerText = eventDay;
  document.getElementById('adminDayDisplay').innerText = eventDay;
  statusEl.innerHTML = '<div class="status-msg status-ok">Event day set to '+n+'.</div>';
  renderShop(); renderAdminList();
}

