/* ===================== NON-STATIC INTERACTIONS ===================== */
// Background blobs drift slightly toward the cursor for a subtle parallax feel.
(function bgParallax(){
  const blobs = document.querySelectorAll('.blob');
  if(!blobs.length) return;
  let raf = null;
  document.addEventListener('mousemove', (e)=>{
    if(raf) return;
    raf = requestAnimationFrame(()=>{
      const nx = (e.clientX / window.innerWidth - 0.5);
      const ny = (e.clientY / window.innerHeight - 0.5);
      blobs.forEach((b,i)=>{
        const strength = 14 + i*8;
        b.style.marginLeft = (nx*strength)+'px';
        b.style.marginTop = (ny*strength)+'px';
      });
      raf = null;
    });
  });
})();

// 3D tilt on shop cards, following the cursor while hovered.
function attachCardTilt(container){
  container.querySelectorAll('.card').forEach((card, i)=>{
    card.style.animationDelay = (i*0.05)+'s';
    card.addEventListener('mousemove', (e)=>{
      const rect = card.getBoundingClientRect();
      const px = (e.clientX - rect.left)/rect.width - 0.5;
      const py = (e.clientY - rect.top)/rect.height - 0.5;
      card.style.setProperty('--tiltX', (px*10)+'deg');
      card.style.setProperty('--tiltY', (-py*10)+'deg');
    });
    card.addEventListener('mouseleave', ()=>{
      card.style.setProperty('--tiltX', '0deg');
      card.style.setProperty('--tiltY', '0deg');
    });
  });
}

// Animates a number element from its current displayed value to a new one, with a little pulse.
function countUpTo(el, newValue){
  if(!el) return;
  const oldValue = parseInt((el.innerText||'0').replace(/[^0-9-]/g,''), 10) || 0;
  newValue = Math.round(newValue);
  if(oldValue === newValue){ el.innerText = fmt(newValue); return; }
  const duration = 500, start = performance.now();
  function step(now){
    const t = Math.min(1, (now-start)/duration);
    const eased = 1 - Math.pow(1-t, 3);
    el.innerText = fmt(Math.round(oldValue + (newValue-oldValue)*eased));
    if(t < 1) requestAnimationFrame(step);
    else {
      el.classList.remove('num-pulse'); void el.offsetWidth; el.classList.add('num-pulse');
    }
  }
  requestAnimationFrame(step);
}
/* Auto-spins gently on its own; click-and-drag spins it faster; hovering
   without dragging gives it a subtle tilt toward the cursor. No more edge
   "barcode" artifact — just the two faces, which is what was glitching. */
(function initCoin3D(){
  const scene = document.getElementById('coin3dScene');
  const coin = document.getElementById('coin3d');
  if(!scene || !coin) return;

  let rotationY = 0, rotationX = 0;
  let dragging = false;
  let lastX = 0;
  let lastTime = null;
  const AUTO_DEG_PER_SEC = 24;
  const DRAG_SENSITIVITY = 0.7;

  function normalize(deg){ const r = deg % 360; return r < 0 ? r + 360 : r; }

  function frame(time){
    if(lastTime === null) lastTime = time;
    const dt = Math.min(time - lastTime, 50);
    lastTime = time;
    if(!dragging) rotationY = normalize(rotationY + AUTO_DEG_PER_SEC * (dt / 1000));
    coin.style.transform = `rotateX(${rotationX}deg) rotateY(${rotationY}deg)`;
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);

  scene.addEventListener('pointerdown', (e)=>{ dragging = true; lastX = e.clientX; scene.setPointerCapture(e.pointerId); });
  scene.addEventListener('pointermove', (e)=>{
    if(dragging){
      const dx = e.clientX - lastX; lastX = e.clientX;
      rotationY = normalize(rotationY + dx * DRAG_SENSITIVITY);
    } else {
      const rect = scene.getBoundingClientRect();
      const cx = rect.left + rect.width/2, cy = rect.top + rect.height/2;
      const nx = (e.clientX - cx) / (rect.width/2), ny = (e.clientY - cy) / (rect.height/2);
      rotationX = Math.max(-18, Math.min(18, -ny * 18));
    }
  });
  function endDrag(){ dragging = false; lastTime = null; }
  scene.addEventListener('pointerup', endDrag);
  scene.addEventListener('pointerleave', ()=>{ endDrag(); rotationX = 0; });
  scene.addEventListener('pointercancel', endDrag);
})();

/* ===================== EASTER EGGS 🥚 ===================== */
(function easterEggs(){
  // 1) Konami code — the classic.
  const KONAMI = ['ArrowUp','ArrowUp','ArrowDown','ArrowDown','ArrowLeft','ArrowRight','ArrowLeft','ArrowRight','b','a'];
  let buffer = [];
  function confettiBurst(){
    const colors = ['#4be3b0','#ffd166','#7db8ff','#ff7a7a','#b98cff'];
    for(let i=0;i<80;i++){
      const el = document.createElement('div');
      el.className = 'confetti-piece';
      el.style.left = Math.random()*100 + 'vw';
      el.style.width = (5+Math.random()*6)+'px';
      el.style.height = (8+Math.random()*10)+'px';
      el.style.background = colors[Math.floor(Math.random()*colors.length)];
      el.style.animationDuration = (2.2+Math.random()*1.6)+'s';
      document.body.appendChild(el);
      setTimeout(()=>el.remove(), 4200);
    }
  }
  document.addEventListener('keydown', (e)=>{
    buffer.push(e.key);
    buffer = buffer.slice(-KONAMI.length);
    if(buffer.join(',') === KONAMI.join(',')){
      confettiBurst();
      toast('🌲 secret unlocked: you have the reflexes of a true hacker 🌲', 'fun');
    }
  });

  // 2) Triple-click the crest for a joke.
  const jokes = [
    "Beep boop. You have unlocked... nothing. Nice try, though. 🤖",
    "This wolf does not, in fact, grant bonus BOBUX. Worth a shot.",
    "You've clicked the logo three times. A admin somewhere felt a disturbance.",
    "🐺 howls appreciatively but remains fiscally unmoved."
  ];
  document.addEventListener('DOMContentLoaded', ()=>{
    document.querySelectorAll('.js-logo').forEach(logo=>{
      let clicks = 0, clickTimer = null;
      logo.addEventListener('click', ()=>{
        clicks++;
        clearTimeout(clickTimer);
        clickTimer = setTimeout(()=>{ clicks = 0; }, 700);
        if(clicks >= 3){
          clicks = 0;
          toast(jokes[Math.floor(Math.random()*jokes.length)], 'fun');
        }
      });
    });
  });

  // 3) A little something for anyone poking around in devtools.
  console.log('%c🌲 psst — nice job opening the console. %cTry the Konami code up top.', 'font-weight:bold;color:#4be3b0;font-size:14px;', 'color:#a9a3e8;');
})();

/* A little rocket occasionally streaks across the screen, because a space hackathon
   site should not sit still. */
(function rocketLaunches(){
  const rocket = document.getElementById('rocketFly');
  if(!rocket) return;
  function launch(){
    rocket.style.display = 'block';
    rocket.classList.remove('launch');
    void rocket.offsetWidth;
    rocket.classList.add('launch');
    setTimeout(()=>{ rocket.style.display = 'none'; }, 4600);
  }
  setTimeout(launch, 2500);
  setInterval(launch, 26000 + Math.random()*8000);
})();

/* Populate the signup form's Orion/Sirius/Polaris/Vega dropdowns — teams
   pick one module from exactly 3 of these 4 groups, skipping the 4th. */
(function populateSignupGroups(){
  const box = document.getElementById('signupGroups');
  if(!box) return;
  const groups = [
    {key:'Orion', id:'signupOrion'},
    {key:'Sirius', id:'signupSirius'},
    {key:'Polaris', id:'signupPolaris'},
    {key:'Vega', id:'signupVega'}
  ];
  box.innerHTML = groups.map(g=>{
    const opts = MODULES.filter(m=>m.group===g.key).map(m=>`<option value="${m.moduleId}">${esc(m.name)}</option>`).join('');
    return `
    <div class="field" style="text-align:left">
      <label style="font-size:11.5px;color:#a9a3e8;font-weight:800">${g.key.toUpperCase()}</label>
      <select id="${g.id}" data-group="${g.key}">
        <option value="">— choose a module —</option>
        ${opts}
      </select>
      <div class="small-note group-lock-note" id="${g.id}LockNote" style="display:none;margin:0">⛔ AUTO-SKIPPED — 3 MODULES CHOSEN</div>
    </div>`;
  }).join('');
  const selects = groups.map(g=>document.getElementById(g.id));
  function syncGroupLocks(){
    const chosen = selects.filter(s=>s && s.value).length;
    if(chosen >= REQUIRED_GROUP_COUNT){
      selects.forEach(sel=>{
        if(sel && !sel.value){
          sel.disabled = true;
          sel.classList.add('locked-choice');
          sel.title = 'Automatically skipped because you already chose 3 modules.';
          const note = document.getElementById(sel.id+'LockNote'); if(note) note.style.display='';
        }
      });
    } else {
      selects.forEach(sel=>{
        if(sel){
          sel.disabled = false;
          sel.classList.remove('locked-choice');
          sel.title = '';
          const note = document.getElementById(sel.id+'LockNote'); if(note) note.style.display='none';
        }
      });
    }
  }
  selects.forEach(sel=>sel.addEventListener('change', syncGroupLocks));
  syncGroupLocks();
})();;

/* Populate the admin "Award Module Points" module dropdown from MODULES. */
(function populateAdminModuleSelect(){
  const sel = document.getElementById('mpModule');
  if(!sel) return;
  sel.innerHTML = MODULES.map(m=>`<option value="${m.moduleId}">${esc(m.name)}</option>`).join('');
})();

/* Populate the shop's "buying for module" dropdown from MODULES. */
(function populateShopModuleSelect(){
  const tribSel = document.getElementById('tpTribulation');
  if(tribSel) tribSel.innerHTML = TRIBULATIONS.map(t=>`<option value="${t.moduleId}">${esc(t.name)}</option>`).join('');
  const sel = document.getElementById('shopModuleSelect');
  if(!sel) return;
  sel.innerHTML = '<option value="">— choose a module —</option>' +
    MODULES.map(m=>`<option value="${m.moduleId}">${esc(m.name)}</option>`).join('');
})();

/* Sitewide refresh button — does a genuine full-page refresh so the whole
   home page (shop, vault, notifications, leaderboard, announcements, market
   status, admin panel — everything) is pulled fresh from the backend, not
   just whichever tab happens to be open. tryAutoLogin() on load signs the
   team/admin straight back in, so this doesn't log anyone out. */
async function refreshEverything(){
  const fab = document.getElementById('refreshFab');
  if(fab) fab.classList.add('spinning');
  try{
    if(isAdmin){
      await refreshState();
      await Promise.all([renderAdminList(),renderAdminBoard(),renderItemOwners(),renderPendingList(),renderAdminNotifications(),populateAdminTeamDropdowns()]);
      toast('Everything refreshed — staying in your current session.', 'ok');
    }else if(currentTeam){
      await refreshState();
      renderAll();
      renderAnnouncements();
      if(document.getElementById('panel-board')?.classList.contains('active')) renderBoard();
      toast('Everything refreshed.', 'ok');
    }else{
      toast('You are not signed in.', 'bad');
    }
  }finally{
    setTimeout(()=>fab && fab.classList.remove('spinning'), 600);
  }
}

/* Refresh shop-hours banner + day every 30s so it stays live during the event. */
setInterval(()=>{
  if(currentTeam){ refreshState(); updateNotifBadge(); }
  if(isAdmin){ updatePendingBadge(); renderAdminNotifications(); }
  if(document.getElementById('panel-board')?.classList.contains('active')) renderBoard();
}, 15000);

/* On load, silently sign the team back in if this device remembers a login. */
tryAutoLogin();

/* The Google script tag is async/defer, so poll briefly until it's ready before rendering buttons. */
(function waitForGoogleSDK(triesLeft){
  if(typeof google !== 'undefined' && google.accounts){ initGoogleSignIn(); return; }
  if(triesLeft <= 0) return;
  setTimeout(()=>waitForGoogleSDK(triesLeft-1), 300);
})(20);